// Smart Diagnostic Rule Engine (No Emojis - Professional Plain Text)
const input = $input.first().json;
const body = input.body || input;
const failedScenarios = body.failedScenarios || [];

const diagnosedIssues = failedScenarios.map((item) => {
  const err = String(item.error || '');
  let category = 'Unknown Failure';
  let rootCause = 'The test threw an unclassified exception.';
  let suggestion = 'Inspect test execution traces in Playwright HTML report.';

  if (err.includes('toBe') || err.includes('toContainText') || err.includes('Expected:')) {
    category = 'Data / Business Rule Mismatch';
    rootCause = 'Expected value differed from actual UI/API output. A calculation or state assertion failed.';
    suggestion = 'Verify if business calculation formula changed or if test mock data is outdated.';
  } else if (err.includes('Timeout') || err.includes('waiting for locator')) {
    category = 'UI Element Missing / Timeout';
    rootCause = 'Playwright waited 5000ms but the target element never appeared in the DOM or remained hidden.';
    suggestion = 'Check if frontend developer changed the data-test attribute or if page is loading slowly.';
  } else if (err.includes('strict mode violation')) {
    category = 'Ambiguous Selector Violation';
    rootCause = 'Locator matched multiple elements instead of exactly one unique element.';
    suggestion = 'Use a more specific selector or add .first() / data-test identifier.';
  } else if (err.includes('429') || err.includes('Too Many Requests')) {
    category = 'API Rate Limiting';
    rootCause = 'The backend or 3rd-party demo service is throttling requests due to too many rapid calls.';
    suggestion = 'Introduce retry backoff or switch from public sandbox to private staging API.';
  } else if (err.includes('ECONNREFUSED') || err.includes('net::ERR_')) {
    category = 'Network / Server Offline';
    rootCause = 'Target host could not be reached. The server might be down or DNS failed.';
    suggestion = 'Verify staging server health and check if local network/VPN is active.';
  }

  return {
    title: item.title,
    file: item.file,
    category,
    rootCause,
    suggestion,
    snippet: err.slice(0, 160).replace(/\n/g, ' ')
  };
});

return {
  ...input,
  diagnosedIssues,
  totalFailed: body.failed || failedScenarios.length || 1,
  totalPassed: body.passed || 0,
  durationSeconds: body.durationSeconds || 0
};
